<div class="d-flex gap-2 flex-wrap no-print"><a class="btn btn-sm btn-outline-secondary" target="_blank" rel="noopener" href="<?= e(url('wing_report_print',['kind'=>$wingReportKind]+$filters)) ?>">Print matching results</a><?php if(\App\Auth::canManage()): ?><form method="post" action="<?= e(url('wing_report_print')) ?>"><?= csrf() ?><input type="hidden" name="_action" value="wing_report_csv"><input type="hidden" name="kind" value="<?= e($wingReportKind) ?>"><?php foreach($filters as $key=>$value): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e($value) ?>"><?php endforeach; ?><button class="btn btn-sm btn-outline-primary" type="submit">Download matching CSV</button></form><?php endif; ?></div>
